import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import '../models/case_model.dart';
import '../state/app_state.dart';
import '../widgets/app_ui.dart';
import 'case_form_screen.dart';

class CaseDetailScreen extends StatelessWidget { final LegalCase item; const CaseDetailScreen({super.key, required this.item}); @override Widget build(BuildContext context) { final current = context.watch<AppState>().cases.firstWhere((c) => c.id == item.id, orElse: () => item); return Scaffold(appBar: AppBar(actions: [IconButton(onPressed: () => Navigator.push(context, MaterialPageRoute(builder: (_) => CaseFormScreen(existing: current))), icon: const Icon(Icons.edit_rounded)), PopupMenuButton<String>(onSelected: (v) { if (v == 'delete') _delete(context, current); }, itemBuilder: (_) => const [PopupMenuItem(value: 'delete', child: Text('Delete case'))])]), body: ListView(padding: const EdgeInsets.fromLTRB(20, 4, 20, 36), children: [_hero(current), const SizedBox(height: 14), _summary(current), const SizedBox(height: 14), if (current.status != CaseStatus.disposed) _actions(context, current), const SizedBox(height: 14), _timeline(current), if (current.outstanding > 0) ...[const SizedBox(height: 14), SurfaceCard(child: Row(children: [const Icon(Icons.payments_outlined, color: danger), const SizedBox(width: 10), const Expanded(child: Text('Fees outstanding', style: TextStyle(fontWeight: FontWeight.w800, color: ink))), Text(rupees(current.outstanding), style: const TextStyle(fontWeight: FontWeight.w900, color: danger))]))]])); }
  Widget _hero(LegalCase c) => Container(padding: const EdgeInsets.all(20), decoration: BoxDecoration(color: ink, borderRadius: BorderRadius.circular(28)), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Row(children: [Expanded(child: Text(c.caseTitle, style: const TextStyle(color: Colors.white, fontSize: 23, fontWeight: FontWeight.w900, height: 1.07))), StatusPill(c.status == CaseStatus.disposed ? (c.disposalResult == DisposalResult.allowed ? 'Allowed' : 'Rejected') : 'Active', color: c.status == CaseStatus.disposed ? const Color(0xFF7EB38E) : gold)]), const SizedBox(height: 8), Text([c.caseNumber, c.clientName, c.opponentName].where((x) => x.isNotEmpty).join(' • '), style: TextStyle(color: Colors.white.withValues(alpha: .68), fontSize: 12))]));
  Widget _summary(LegalCase c) => SurfaceCard(child: Column(children: [_row(Icons.account_balance_rounded, 'Court', c.court), _row(Icons.gavel_rounded, 'Judge / authority', c.judge), _row(Icons.menu_book_rounded, 'Sections', c.sections), _row(Icons.event_rounded, 'Next hearing', c.nextHearing == null ? 'Not set' : '${fmtDate(c.nextHearing)}${c.hearingPurpose.isEmpty ? '' : ' • ${c.hearingPurpose}'}'), _row(Icons.person_outline_rounded, 'Client', c.clientName), _row(Icons.phone_outlined, 'Contact', c.clientContact.isEmpty ? 'Not set' : c.clientContact)]));
  Widget _row(IconData icon, String label, String value) => Padding(padding: const EdgeInsets.symmetric(vertical: 8), child: Row(crossAxisAlignment: CrossAxisAlignment.start, children: [Icon(icon, size: 19, color: gold), const SizedBox(width: 12), SizedBox(width: 115, child: Text(label, style: const TextStyle(fontSize: 12, color: muted))), Expanded(child: Text(value.isEmpty ? 'Not set' : value, style: const TextStyle(fontSize: 13, fontWeight: FontWeight.w700, color: ink)))]));
  Widget _actions(BuildContext context, LegalCase c) => Row(children: [Expanded(child: OutlinedButton.icon(onPressed: () => _update(context, c), icon: const Icon(Icons.bolt_rounded), label: const Text('Update case'))), const SizedBox(width: 10), Expanded(child: FilledButton.icon(onPressed: () => _dispose(context, c), icon: const Icon(Icons.verified_rounded), label: const Text('Dispose')))]);
  Widget _timeline(LegalCase c) { final updates = [...c.updates]..sort((a,b) => b.date.compareTo(a.date)); return Column(crossAxisAlignment: CrossAxisAlignment.start, children: [const Padding(padding: EdgeInsets.only(left: 3, bottom: 10), child: Text('Case history', style: TextStyle(fontSize: 18, fontWeight: FontWeight.w900, color: ink))), if (updates.isEmpty) SurfaceCard(child: const Text('No updates recorded yet. Use Update case after each hearing to build a reliable history.', style: TextStyle(color: muted, height: 1.45))) else ...updates.map((u) => Padding(padding: const EdgeInsets.only(bottom: 10), child: SurfaceCard(child: Row(crossAxisAlignment: CrossAxisAlignment.start, children: [Container(width: 10, height: 10, margin: const EdgeInsets.only(top: 5), decoration: const BoxDecoration(color: gold, shape: BoxShape.circle)), const SizedBox(width: 12), Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text(fmtDay(u.date), style: const TextStyle(fontSize: 11, color: muted, fontWeight: FontWeight.w700)), const SizedBox(height: 5), Text(u.outcome, style: const TextStyle(fontWeight: FontWeight.w900, color: ink)), if (u.nextDate != null) ...[const SizedBox(height: 4), Text('Next date: ${fmtDate(u.nextDate)}', style: const TextStyle(fontSize: 12, color: muted))], if (u.note.isNotEmpty) ...[const SizedBox(height: 7), Text(u.note, style: const TextStyle(color: muted, height: 1.35))]]))]))))]); }
  Future<void> _update(BuildContext context, LegalCase c) async { final outcome = TextEditingController(); final note = TextEditingController(); DateTime? next = c.nextHearing; await showModalBottomSheet(context: context, isScrollControlled: true, showDragHandle: true, builder: (_) => Padding(padding: EdgeInsets.fromLTRB(20, 10, 20, MediaQuery.viewInsetsOf(context).bottom + 24), child: StatefulBuilder(builder: (context, setLocal) => Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.start, children: [const Text('Update today', style: TextStyle(fontSize: 21, fontWeight: FontWeight.w900, color: ink)), const SizedBox(height: 12), TextField(controller: outcome, maxLines: 3, decoration: fieldDecoration('What happened today *', hint: 'Arguments, order, adjournment, compliance…')), const SizedBox(height: 12), TextField(controller: note, maxLines: 3, decoration: fieldDecoration('Notes')), const SizedBox(height: 12), ListTile(contentPadding: EdgeInsets.zero, title: const Text('Next hearing date', style: TextStyle(fontWeight: FontWeight.w700)), subtitle: Text(fmtDate(next)), trailing: const Icon(Icons.calendar_month_rounded, color: gold), onTap: () async { final d = await showDatePicker(context: context, firstDate: DateTime.now(), lastDate: DateTime(2100), initialDate: next ?? DateTime.now()); if (d != null) setLocal(() => next = d); }), FilledButton(onPressed: () async { if (outcome.text.trim().isEmpty) return; await context.read<AppState>().addUpdate(c, outcome: outcome.text.trim(), nextDate: next, note: note.text.trim()); if (context.mounted) Navigator.pop(context); }, child: const SizedBox(width: double.infinity, child: Center(child: Text('Save update'))))])))); outcome.dispose(); note.dispose(); }
  Future<void> _dispose(BuildContext context, LegalCase c) async { final choice = await showDialog<DisposalResult>(context: context, builder: (_) => AlertDialog(title: const Text('Dispose case'), content: const Text('Choose the final result recorded in CaseCraft.'), actions: [TextButton(onPressed: () => Navigator.pop(context), child: const Text('Cancel')), OutlinedButton(onPressed: () => Navigator.pop(context, DisposalResult.rejected), child: const Text('Rejected')), FilledButton(onPressed: () => Navigator.pop(context, DisposalResult.allowed), child: const Text('Allowed'))])); if (choice == null || !context.mounted) return; await context.read<AppState>().disposeCase(c, choice); if (context.mounted) Navigator.pop(context); }
  Future<void> _delete(BuildContext context, LegalCase c) async { final ok = await showDialog<bool>(context: context, builder: (_) => AlertDialog(title: const Text('Delete case?'), content: const Text('This permanently removes the case and its history from this device.'), actions: [TextButton(onPressed: () => Navigator.pop(context, false), child: const Text('Cancel')), FilledButton(onPressed: () => Navigator.pop(context, true), child: const Text('Delete'))])); if (ok == true && context.mounted) { await context.read<AppState>().deleteCase(c); if (context.mounted) Navigator.pop(context); } }
}
